  $digmjson${"slug": "digital-marketing", "title": "Digital Marketing", "description": "Set goals, audiences, value propositions, funnels, and channel roles for integrated digital campaigns, then cover owned media, search, content, lifecycle, social, partnerships, paid media, omnichannel, martech, analytics, attribution, privacy, and a campaign capstone.", "topics": [{"id": "1d89cc99-d950-40e8-90fa-c2500ce94c3d", "type": "topic", "title": "Digital Marketing Strategy and Customer Journey", "description": "Set goals, audiences, value propositions, funnels, and channel roles for integrated digital campaigns.", "children": [{"id": "3f132a14-525f-4e83-9c3d-68e679cd1cea", "type": "subtopic", "title": "Strategic role of digital marketing", "children": [{"id": "90218716-fd10-4471-bc38-311393181698", "type": "concept", "title": "Business objectives versus channel objectives"}, {"id": "169bd516-80c3-4cc0-815d-f3431b58b8e0", "type": "concept", "title": "Paid, owned, earned, and shared media roles"}, {"id": "d0957730-1ad0-45fd-8edf-dcc02be5b4d6", "type": "concept", "title": "Funnel, flywheel, and customer journey models"}, {"id": "93bfe112-d589-46e5-9e50-c35166161469", "type": "concept", "title": "Budgeting and resource allocation basics"}], "description": "This subtopic frames digital marketing as a business discipline, not a bundle of channel tactics. Students learn how digital activity should support revenue, brand equity, customer experience, and organizational goals."}, {"id": "24cb3c98-e425-4b3f-99ba-41bc894c0fae", "type": "subtopic", "title": "Audience, positioning, and value proposition", "children": [{"id": "4adcf879-502d-4624-9182-a4ceb7c69e75", "type": "concept", "title": "Ideal customer profiles and personas"}, {"id": "7425a61d-c02e-4b93-bef9-b84a2191ef10", "type": "concept", "title": "Jobs-to-be-done and pain point mapping"}, {"id": "5fe325ef-e692-4079-9abf-663c655297fc", "type": "concept", "title": "Differentiation and value proposition design"}, {"id": "f0d7c2bb-e545-41c2-a4b2-e7f1056dcb0f", "type": "concept", "title": "Message hierarchy and proof points"}], "description": "Digital strategy starts with a clear promise to a clearly defined audience. This section connects segmentation, targeting, positioning, and message strategy to campaign design."}, {"id": "78b5ad2e-e7f6-40ba-b591-0f3a96c4fade", "type": "subtopic", "title": "Campaign architecture", "children": [{"id": "3135a162-6259-4a2e-960a-06df8b9fbb86", "type": "concept", "title": "Campaign brief structure"}, {"id": "5128f7da-cc65-42e5-a079-cc7d5d791285", "type": "concept", "title": "Channel mix and sequencing"}, {"id": "39024653-5fd8-400c-a0b4-e6b9105abd34", "type": "concept", "title": "Creative testing roadmap"}, {"id": "0e188ae1-3b2f-4fdd-a4a3-05f63d4ef864", "type": "concept", "title": "Learning agenda and optimization cadence"}], "description": "Students learn to translate strategy into an integrated campaign plan with channels, creative, timing, measurement, and optimization loops."}]}, {"id": "5f928662-ffca-4582-994f-cd7c9f848aa7", "type": "topic", "title": "Digital Consumer Behavior, Research, and Segmentation", "description": "Use digital behavior data, personas, journeys, and segmentation to make customer-centered decisions.", "children": [{"id": "0d2aa4da-54ca-4ea3-941c-91e86fd53281", "type": "subtopic", "title": "Digital behavior and decision journeys", "children": [{"id": "c54cf97e-fb8e-4fc6-aac0-c67a0509bd02", "type": "concept", "title": "Micro-moments and intent states"}, {"id": "8684da76-4b0b-4ef3-8e74-2edfc793c330", "type": "concept", "title": "Awareness, consideration, conversion, loyalty, and advocacy"}, {"id": "40cb3174-6fc6-412f-897f-aef3b387bbbb", "type": "concept", "title": "Trust signals, reviews, and social proof"}, {"id": "de9668bc-2b55-48d5-a720-4daeda06c478", "type": "concept", "title": "Device, context, and attention constraints"}], "description": "This subtopic explains how consumers search, compare, trust, share, and buy in digital environments. The goal is to avoid guessing and instead design around observable behavior."}, {"id": "d9c22ff5-866d-4b9d-940b-f5e739077f12", "type": "subtopic", "title": "Research methods for digital marketers", "children": [{"id": "4aa96a2e-0985-49ec-8d47-c5fce9dfde86", "type": "concept", "title": "Surveys, interviews, reviews, and social listening"}, {"id": "3dc0ee57-959d-40d0-a400-4ba1843538ad", "type": "concept", "title": "Keyword, competitor, and market research"}, {"id": "6c242bff-878b-4adc-b0a9-7b12ff4a6728", "type": "concept", "title": "Web analytics and CRM data as research inputs"}, {"id": "ea80c21d-eba1-4bf7-81ac-4eed8f24d977", "type": "concept", "title": "Bias, sample quality, and data limits"}], "description": "Students learn how to combine qualitative and quantitative sources to understand audiences before building campaigns."}, {"id": "87c392e7-0c5a-4ab3-a388-2111c1f30a58", "type": "subtopic", "title": "Segmentation and targeting", "children": [{"id": "da1139d6-eeaa-409b-ac51-245d74cc02d2", "type": "concept", "title": "Demographic, psychographic, behavioral, and value-based segments"}, {"id": "4a4586bc-9009-433e-bb56-f956c7705bfc", "type": "concept", "title": "RFM, CLV, loyalty, and lifecycle segments"}, {"id": "bf65d856-047b-480f-a508-dfe84ec718db", "type": "concept", "title": "Lookalike audiences and modeled targeting"}, {"id": "44f505df-8c94-4f1a-a11e-0b827a6e9ff1", "type": "concept", "title": "Avoiding exclusionary or sensitive targeting"}], "description": "Segmentation turns broad audiences into actionable groups. This section introduces meaningful segmentation criteria and responsible targeting choices."}]}, {"id": "7a73f587-f7ca-4867-b059-cf062c2efdf2", "type": "topic", "title": "Owned Media, Websites, UX, and Conversion Foundations", "description": "Treat websites, landing pages, and conversion paths as the operational center of digital marketing.", "children": [{"id": "c4040f16-782d-4a29-aee0-3827a720be79", "type": "subtopic", "title": "Website strategy and information architecture", "children": [{"id": "c989ea16-db46-4e65-a401-5178d132f650", "type": "concept", "title": "Homepage, landing page, product page, and resource hub roles"}, {"id": "913c90e5-3849-4364-a81e-57c2e5da647d", "type": "concept", "title": "Information scent and findability"}, {"id": "ab5b3fea-d797-4a8e-b6c1-52696e74825a", "type": "concept", "title": "Calls to action and conversion paths"}, {"id": "646b47be-4e47-45d9-9783-6027d2fc1ad6", "type": "concept", "title": "Trust, accessibility, and performance signals"}], "description": "Owned media is where many campaigns convert interest into action. Students learn how site structure, navigation, and content hierarchy shape performance."}, {"id": "dd99c53b-c754-4d86-9ce5-09b2ad94c679", "type": "subtopic", "title": "UX and usability for marketers", "children": [{"id": "f9e0c0b3-0c19-4eed-aab9-6575d7b49eb9", "type": "concept", "title": "User goals and task flows"}, {"id": "3025eded-85f0-40b7-bbf8-837f108dc409", "type": "concept", "title": "Form design and checkout friction"}, {"id": "c774f281-0e6f-485b-ab88-1660d3f90554", "type": "concept", "title": "Mobile-first usability"}, {"id": "c9da0bb2-e1a3-490e-93e8-1ef5850cd6b4", "type": "concept", "title": "Usability testing and heuristic review"}], "description": "This subtopic introduces user experience concepts marketers need to diagnose friction and improve campaign outcomes."}, {"id": "40b417aa-1153-441b-920b-2efd0bb3ba38", "type": "subtopic", "title": "Conversion rate optimization foundations", "children": [{"id": "2075b62c-8f7f-4cf5-b60f-4293d7eac421", "type": "concept", "title": "Conversion funnels and drop-off analysis"}, {"id": "c604a343-f524-4c43-aa44-f8a88b078169", "type": "concept", "title": "Landing page message match"}, {"id": "a4cd4a85-9cb1-4dcf-a7ae-18719257c2c3", "type": "concept", "title": "Heatmaps, session recordings, and qualitative feedback"}, {"id": "e49cdbde-51f5-4c3e-8552-eaafa60fcdf5", "type": "concept", "title": "Hypothesis writing and prioritization frameworks"}], "description": "Students learn to treat conversion improvement as a disciplined process of diagnosis, hypothesis, testing, and iteration."}]}, {"id": "51f9dd89-4f62-45b0-9edf-e2523817b0e7", "type": "topic", "title": "Search Engine Optimization and Organic Discoverability", "description": "Build search visibility through intent research, technical SEO, content quality, authority, and measurement.", "children": [{"id": "c66a3641-fc1a-4361-9244-29dd73bc752a", "type": "subtopic", "title": "Search intent and keyword strategy", "children": [{"id": "19b3c18a-294b-4df0-8812-bf94b871002c", "type": "concept", "title": "Informational, commercial, navigational, and transactional intent"}, {"id": "11efdf9c-42b4-4e58-9221-8909326911d5", "type": "concept", "title": "Keyword clusters and topic maps"}, {"id": "29b0037b-62d9-4bfb-a6f4-ff510309bd7f", "type": "concept", "title": "Search volume, difficulty, and business value"}, {"id": "bc76583b-3818-4b94-a1b5-18d8d309ac92", "type": "concept", "title": "SERP features and zero-click behavior"}], "description": "SEO begins with understanding what people are trying to accomplish when they search. Students learn to map queries to intent and content formats."}, {"id": "d13e4e3c-d1df-4f82-ac2c-5237123d14f5", "type": "subtopic", "title": "On-page and content SEO", "children": [{"id": "26afedaa-cb81-4762-917f-8dc058027083", "type": "concept", "title": "Titles, headings, metadata, and internal linking"}, {"id": "72c038ab-0c34-46f8-a7b4-b35a5e24ba63", "type": "concept", "title": "E-E-A-T and content quality signals"}, {"id": "a9c6ef40-7b96-4feb-aaeb-ebdd35b5766c", "type": "concept", "title": "Content refreshes and pruning"}, {"id": "84cb7fe2-6de1-4fd1-9abf-44b081f8a9c8", "type": "concept", "title": "Image, video, and structured content optimization"}], "description": "This subtopic covers how useful, trustworthy content becomes discoverable and persuasive."}, {"id": "de5bf2cd-7ff0-4a8c-999d-12106d0f8546", "type": "subtopic", "title": "Technical SEO and authority", "children": [{"id": "19fa406f-758a-4d72-a04f-d5472465e5cc", "type": "concept", "title": "Crawlability, indexability, sitemaps, and robots rules"}, {"id": "f743b13e-0d1e-406e-9134-ce56d820c627", "type": "concept", "title": "Core Web Vitals and page speed"}, {"id": "4747470e-4237-4990-b806-0160d3ca4412", "type": "concept", "title": "Schema markup and structured data"}, {"id": "a8fe8bc0-35c8-4430-9b81-fcd1c9ce439c", "type": "concept", "title": "Backlinks, digital PR, and authority building"}], "description": "Students learn the infrastructure and reputation signals that affect organic visibility."}]}, {"id": "bd6db8f4-216e-4ed0-98c8-d61b4082a00e", "type": "topic", "title": "Paid Search, SEM, and Intent Capture", "description": "Plan, launch, and optimize search campaigns that connect customer intent to measurable business outcomes.", "children": [{"id": "0f687881-eaad-4147-ac99-93f9f4d2b9c9", "type": "subtopic", "title": "Search campaign structure", "children": [{"id": "6f681bd7-b453-4477-9138-2165bf4e2b71", "type": "concept", "title": "Accounts, campaigns, ad groups, keywords, and match types"}, {"id": "71f24e89-523f-41a2-9a04-065f05fbba19", "type": "concept", "title": "Ad copy, assets, and landing page alignment"}, {"id": "45dab8c4-8769-430d-8896-6f637b068475", "type": "concept", "title": "Negative keywords and query management"}, {"id": "6783cf47-28b2-4eb3-b53a-6f343d1126be", "type": "concept", "title": "Brand versus non-brand strategy"}], "description": "Paid search teaches students how to meet demand at the moment of intent. This subtopic covers the basic architecture of search accounts."}, {"id": "baf4a2fe-1479-4152-a803-f54133d2ba57", "type": "subtopic", "title": "Bidding, budgets, and optimization", "children": [{"id": "55c64605-c512-4415-848d-e39083d75842", "type": "concept", "title": "Quality Score and ad rank concepts"}, {"id": "5330af1c-1db0-4318-aa27-7950bbb0933b", "type": "concept", "title": "Manual 