description": "Students connect lifecycle marketing to revenue, CLV, customer success, and retention."}]}, {"id": "50420ad2-5765-4011-8f74-b4919b48e2ae", "type": "topic", "title": "Social Media Marketing and Community Management", "description": "Design platform-specific social strategies, content calendars, engagement practices, and community norms.", "children": [{"id": "57299d81-b4f6-4a68-9a96-39c49e185a49", "type": "subtopic", "title": "Platform strategy", "children": [{"id": "0b0e0004-eb25-4b69-a765-bc205899362c", "type": "concept", "title": "Instagram, TikTok, LinkedIn, YouTube, X, Reddit, and emerging platforms"}, {"id": "be37632d-65a1-44e7-a61a-d35fda5666f4", "type": "concept", "title": "Platform affordances and algorithmic feeds"}, {"id": "0a189e4f-a266-4c67-b136-4da3f6b34cd2", "type": "concept", "title": "Organic versus paid social roles"}, {"id": "63b131db-9dc5-469f-b952-55a33c1dea06", "type": "concept", "title": "B2B versus B2C platform selection"}], "description": "Different platforms reward different behaviors. Students learn to choose platforms based on audience, format, culture, and campaign objectives."}, {"id": "eb507e37-7928-4f18-a4ca-6e2b94a6e2d9", "type": "subtopic", "title": "Community and engagement", "children": [{"id": "4f2431a7-e26a-4b25-87bf-3215891920a9", "type": "concept", "title": "Community guidelines and response playbooks"}, {"id": "dc343f13-1786-446a-b5bc-df98e7190e49", "type": "concept", "title": "Social listening and sentiment analysis"}, {"id": "143d4600-9b03-4295-8476-5036029d1a88", "type": "concept", "title": "Comment moderation and escalation"}, {"id": "6e296336-0d45-42a6-a1dd-5c6fdf78f37b", "type": "concept", "title": "Brand voice, tone, and conversational norms"}], "description": "Social media is partly a relationship system. This subtopic teaches listening, response, moderation, and brand voice."}, {"id": "66b990f1-bc7e-4c8a-9c10-cf5c03cec3eb", "type": "subtopic", "title": "Social content operations", "children": [{"id": "57fdc753-57af-414f-b1f9-2d4de9c8ac31", "type": "concept", "title": "Content calendars and production workflows"}, {"id": "de6f3e00-3141-4828-9eca-4ad36d370cf2", "type": "concept", "title": "Short-form video and creator-native formats"}, {"id": "dead78d9-7c22-452b-96d1-aa1f9ad27e5d", "type": "concept", "title": "Engagement, share, save, and watch-time metrics"}, {"id": "90ba6d87-381e-49a2-9d96-2472725085ce", "type": "concept", "title": "Platform reporting and trend analysis"}], "description": "Students learn the discipline behind consistent social publishing and performance improvement."}]}, {"id": "36b85157-7af1-444d-954e-35e1c13407dc", "type": "topic", "title": "Creator, Influencer, Affiliate, and Partnership Marketing", "description": "Evaluate partnership models, creator fit, affiliate economics, disclosure rules, and campaign governance.", "children": [{"id": "c2308e1a-2ae6-4729-acd8-96f07ea3859a", "type": "subtopic", "title": "Creator and influencer strategy", "children": [{"id": "bb8ceb6f-5700-43f0-a5d0-cbfa7ad1da23", "type": "concept", "title": "Creator tiers and community fit"}, {"id": "c8eb165d-aeee-44ca-99d1-aee298184869", "type": "concept", "title": "Authenticity, trust, and content style"}, {"id": "d0d6aca7-9b9d-4d32-965f-036f4f297adc", "type": "concept", "title": "Briefing creators without over-controlling content"}, {"id": "663ab182-1edc-44a8-a364-cde443781e2b", "type": "concept", "title": "Usage rights and content repurposing"}], "description": "Students learn how to evaluate whether a creator partnership fits the brand, audience, and objective."}, {"id": "19e4ac81-f875-411b-b7ef-73ae533bda98", "type": "subtopic", "title": "Affiliate and partner economics", "children": [{"id": "44b0d51b-1645-4792-b32a-ce14bf1568be", "type": "concept", "title": "Affiliate networks and tracking links"}, {"id": "b90bf352-85d0-4424-9d0c-05052baf5580", "type": "concept", "title": "Commission structures and payout rules"}, {"id": "d752f625-3585-407c-bfab-ddc6bb62b9b5", "type": "concept", "title": "Coupon, loyalty, review, and publisher partners"}, {"id": "5a0aa7b3-716c-4787-abac-ae8ed56ef731", "type": "concept", "title": "Fraud, incrementality, and cannibalization risks"}], "description": "This subtopic covers performance-based partnerships and how incentives shape behavior."}, {"id": "513951f8-2a1d-4cfb-a3d4-f15e403d9e71", "type": "subtopic", "title": "Governance and disclosure", "children": [{"id": "57ba2989-4d98-4de6-96fb-4fea475972c0", "type": "concept", "title": "FTC endorsement disclosures"}, {"id": "e063b763-32c1-4457-8796-5ecf6e0b25c9", "type": "concept", "title": "Brand safety and reputational fit"}, {"id": "6e54da4a-1b46-48da-8a38-9fbca445dac7", "type": "concept", "title": "Contracts, deliverables, and approvals"}, {"id": "e3e95fb3-40a5-4402-bee0-3406c924a8c7", "type": "concept", "title": "Campaign reporting and creator scorecards"}], "description": "Students learn the legal and ethical responsibilities that come with sponsored influence."}]}, {"id": "85690b02-0de4-4b05-aac6-795aef7fa2f6", "type": "topic", "title": "Display, Programmatic, Paid Social, Video, and Retail Media", "description": "Understand modern paid media buying across audiences, placements, creative formats, and marketplaces.", "children": [{"id": "e6c5619f-0a88-4141-bb98-8b9ccba7f6ae", "type": "subtopic", "title": "Programmatic and display fundamentals", "children": [{"id": "1f29b48a-935e-421c-a7cd-e64686c5f796", "type": "concept", "title": "DSPs, SSPs, exchanges, and ad networks"}, {"id": "95577283-533d-4699-8769-b3c314ee327a", "type": "concept", "title": "Audience targeting and contextual targeting"}, {"id": "17f706c3-fa0f-43b8-8504-95adb5536657", "type": "concept", "title": "Viewability, frequency, reach, and waste"}, {"id": "992ce221-b35f-4f37-bbee-914534651a80", "type": "concept", "title": "Fraud, brand safety, and verification"}], "description": "Programmatic media introduces automated buying, audience targeting, and marketplace dynamics. Students learn the vocabulary and tradeoffs."}, {"id": "9759207f-05d1-4c52-b52b-68e46019888b", "type": "subtopic", "title": "Paid social and video advertising", "children": [{"id": "9fa5f094-d958-4f79-8987-2763b3e055ed", "type": "concept", "title": "Creative hooks and thumb-stopping formats"}, {"id": "8e96fb76-52c0-4699-bad6-939e5b85e987", "type": "concept", "title": "Audience testing and lookalikes"}, {"id": "abb9adf0-1f39-425a-8731-785a08b31be3", "type": "concept", "title": "Video completion, view-through, and engagement metrics"}, {"id": "2f27fca2-17a2-4716-b213-f56704bc1915", "type": "concept", "title": "Creative fatigue and refresh cycles"}], "description": "This subtopic covers creative, targeting, and optimization for feed, story, short-form video, and streaming environments."}, {"id": "69de43ac-5ef3-49e4-99a8-92deb0828fd9", "type": "subtopic", "title": "Retail media and marketplace advertising", "children": [{"id": "8a4bdf18-6bea-40a5-b8e4-719d026c2d44", "type": "concept", "title": "Amazon Ads, Walmart Connect, Instacart, and marketplace media"}, {"id": "35d2aa11-7675-4191-b1a9-65523cbfddef", "type": "concept", "title": "Sponsored products, display, and brand stores"}, {"id": "34a18d28-f948-46f1-82c5-2d92449bf718", "type": "concept", "title": "Commerce data and closed-loop measurement"}, {"id": "901fbe69-b5f8-415c-8814-67cc35c82b4d", "type": "concept", "title": "Margin, inventory, and retail readiness"}], "description": "Retail media has become a major digital channel. Students learn why commerce platforms are both media owners and sales channels."}]}, {"id": "e59befa7-5dd4-415e-86c9-54773351030b", "type": "topic", "title": "Mobile, Local, Commerce, and Omnichannel Marketing", "description": "Connect mobile behavior, local search, ecommerce, marketplaces, and offline touchpoints into one customer experience.", "children": [{"id": "dba6b66d-6237-4531-aeca-4716d99a44c7", "type": "subtopic", "title": "Mobile marketing behavior", "children": [{"id": "fd0d9559-edde-4e3a-9999-2fa751b2091b", "type": "concept", "title": "Mobile-first landing pages and forms"}, {"id": "f8007e1e-c6fe-4a02-934f-5e6fa2e200cc", "type": "concept", "title": "SMS, push, in-app, and wallet messaging"}, {"id": "4b8d9ce3-b066-4198-8322-893ec75eed16", "type": "concept", "title": "App acquisition and retention"}, {"id": "efdccdf3-9873-4500-b6bf-b0eafd958c11", "type": "concept", "title": "Location signals and proximity marketing"}], "description": "Mobile is the default digital context for many customers. Students learn how screen size, location, notifications, and app ecosystems change strategy."}, {"id": "d020b174-0802-45c2-9948-0c1e7cfc1a89", "type": "subtopic", "title": "Ecommerce and marketplace journeys", "children": [{"id": "2df182d9-5252-4289-a41d-91b99491323f", "type": "concept", "title": "Product detail pages and merchandising"}, {"id": "ffb956f1-59e2-428c-a541-5a664ec26245", "type": "concept", "title": "Cart abandonment and checkout optimization"}, {"id": "9972cb1e-f9fd-4c75-865a-5ff8b18f04da", "type": "concept", "title": "Ratings, reviews, and social proof"}, {"id": "b3bd0ca5-41b8-4251-9b5f-1c7a2e5d578e", "type": "concept", "title": "Returns, customer service, and loyalty"}], "description": "This subtopic connects digital marketing to product discovery, checkout, merchandising, and post-purchase experience."}, {"id": "d771c30f-a9ce-4d4a-8cfc-2dd4e00ea8fc", "type": "subtopic", "title": "Omnichannel integration", "children": [{"id": "66db2678-47ba-4ded-b134-1efc0d7e04e6", "type": "concept", "title": "Online-to-store journeys"}, {"id": "924d438e-9d82-4050-b43c-9f87a7debdfb", "type": "concept", "title": "CRM, POS, ecommerce, and call-center data"}, {"id": "10dc3000-efa2-4ff7-91c8-159b5bc7d8a0", "type": "concept", "title": "Consistent messaging across touchpoints"}, {"id": "b9c8c8c3-3c33-4681-8033-c60e0028df26", "type": "concept", "title": "Channel conflict and attribution challenges"}], "description": "Students learn to design campaigns that work across online and offline touchpoints."}]}, {"id": "b08078fa-bc37-4e2e-9a6c-586de0efe10b", "type": "topic", "title": "Martech, Automation, Data Infrastructure, and AI-Assisted Marketing", "description": "Map the tools, data flows, automation rules, and AI workflows that power modern digital campaigns.", "children": [{"id": "c5984fbe-97f3-40c7-8c28-19ff7da70be8", "type": "subtopic", "title": "Marketing technology stack", "children": [{"id": "6d81d116-7728-44d4-bdd4-4efe37273b5e", "type": "concept", "title": "CMS, CRM, MAP, CDP, analytics, tag manager, and ad platforms"}, {"id": "b320b24e-6b85-4750-8a57-d10fd9c57214", "type": "concept", "title": "Data flows and integrations"}, {"id": "47db77e8-74d8-44ee-9226-016afe301a57", "type": "concept", "title": "Build versus buy decisions"}, {"id": "6ed8d425-ead3-42c3-b037-87001bb746b8", "type": "concept", "title": "Vendor evaluation and governance"}], "description": "Students learn what tools modern teams use and how those tools fit together."}, {"id": "c5b962be-eccf-40cc-9fff-70a2b636d130", "type": "subtopic", "title": "Automation and personalization", "children": [{"id": "b8e2e164-e1d0-4e7f-a334-1a7bb83f9147", "type": "concept", "title": "Trigger events and journey orchestration"}, {"id": "f938df34-df29-4609-80bd-def2f9c69e25", "type": "concept", "title": "Lead scoring and nurture logic"}, {"id": "dd74cde3-20b7-4457-8f48-89821fd00e90", "type": "concept", "title": "Recommendation and personalization rules"}, {"id": "2aa9a005-f176-4408-8c1a-08435203c710", "type": "concept", "title": "Error handling, QA, and suppression logic"}], "description": "Automation is useful only when it respects customer context. This subtopic covers triggers, rules, segmentation, and guardrails."}, {"id": "d01fa3d8-1f41-45c7-917d-32c8a661e1cf", "type": "subtopic", "title": "AI-assisted marketing workflows", "children": [{"id": "cdb98066-47b3-4cc8-9c47-6c518d11149f", "type": "concept", "title": "Prompting and human review"}, {"id": "3979e51e-575e-43f9-bd44-437eae6c9834", "type": "concept", "title": "Creative ideation and variant generation"}, {"id": "98f98764-7d9f-4829-ac9e-eac34d3d0cfa", "type": "concept", "title": "Synthetic insights versus real customer evidence"}, {"id": "b9c2a3cf-27c6-4823-84a4-afb490e6cd94", "type": "concept", "title": "Bias, hallucination, copyright, and brand voice controls"}], "description": "Students learn practical and responsible uses of AI in research, content, creative iteration, and analysis."}]}, {"id": "d87d00fb-ee01-48d9-8221-5f8b035927d5", "type": "topic", "title": "Analytics, KPIs, Dashboards, Tagging, and Reporting", "description": "Translate campaign activity into reliable measurement plans, dashboards, and decision-ready reporting.", "children": [{"id": "17a5108d-e869-4c73-9326-b0fc71961d29", "type": "subtopic", "title": "Measurement planning", "children": [{"id": "7c41e149-64f7-4b3c-9867-8dbcb97857b7", "type": "concept", "title": "Business goal to KPI mapping"}, {"id": "ebaa9f8e-b96e-45c7-983f-f0586728691d", "type": "concept", "title": "Primary, secondary, and diagnostic metrics"}, {"id": "a3c1037b-e822-4d80-978c-4877c9d53910", "type": "concept", "title": "UTM conventions and campaign taxonomy"}, {"id": "6e0ae1de-c64b-4ab8-817a-370efccdb368", "type": "concept", "title": "Benchmarks and targets"}], "description": "This subtopic teaches students to define success before launching campaigns."}, {"id": "b28f05b0-f8e6-4362-8c6c-068e67b66519", "type": "subtopic", "title": "Analytics implementation", "children": [{"id": "d795cd3f-644e-4a6a-aadf-341e8404cfcf", "type": "concept", "title": "GA4 events, conversions, and audiences"}, {"id": "19eb6add-5e0e-49c8-8571-bb3c441f5726", "type": "concept", "title": "Tag managers and pixels"}, {"id": "bc77e678-e670-40e1-8dfc-9ee94d33171e", "type": "concept", "title": "Server-side tagging and consent mode concepts"}, {"id": "fce7a39c-e215-45c6-83e5-29e11cc5c9b1", "type": "concept", "title": "Data QA, naming conventions, and documentation"}], "description": "Students learn why reliable reporting depends on technical setup and governance."}, {"id": "46263746-5d42-4d4a-bc4f-9d0c0a958b87", "type": "subtopic", "title": "Dashboards and storytelling with data", "children": [{"id": "95601928-9047-4f6c-b27c-855a7293b68b", "type": "concept", "title": "Executive versus operator dashboards"}, {"id": "7bbdccca-50e7-4652-b142-31462a6098bf", "type": "concept", "title": "Cohorts, funnels, and segments"}, {"id": "084ce085-641b-41b1-b926-68e93bfa464f", "type": "concept", "title": "Variance, causality, and context"}, {"id": "62725980-9b3e-4c8e-8e74-5b78006bdfc4", "type": "concept", "title": "Insights, recommendations, and next actions"}], "description": "Reporting should drive decisions, not just display charts. Students learn to make dashboards readable and action-oriented."}]}, {"id": "28d48ccc-ba84-45f4-ad6e-fb3c895caad7", "type": "topic", "title": "Attribution, Incrementality, Experimentation, and Growth Optimization", "description": "Move beyond last-click reporting with tests, lift studies, attribution models, and conversion optimization.", "children": [{"id": "21c16111-b2bb-4181-ab9b-5215c564deb1", "type": "subtopic", "title": "Attribution models and their limits", "children": [{"id": "7149a66c-0402-4f97-a1e3-1b87d879e956", "type": "concept", "title": "Last click, first click, linear, position-based, and data-driven attribution"}, {"id": "3c175730-7686-4186-aabe-669e07ac30c6", "type": "concept", "title": "Cross-device and offline gaps"}, {"id": "47d2a380-58d7-4918-ae34-390fc9ab6361", "type": "concept", "title": "Walled gardens and measurement loss"}, {"id": "a0e1980d-5ab4-496a-8c36-d7ece4f4388e", "type": "concept", "title": "Attribution versus causality"}], "description": "Students learn why attribution is useful but incomplete. The goal is to understand what models can and cannot prove."}, {"id": "50d45743-c4fa-4ce1-bc7d-65f2bacfc5dd", "type": "subtopic", "title": "Incrementality and experimentation", "children": [{"id": "6225928e-4e0a-4ae3-aa15-75f4e73c040e", "type": "concept", "title": "A/B and multivariate testing"}, {"id": "09d8ffc3-c955-414c-aef1-2598a9dbc2d5", "type": "concept", "title": "Geo tests and holdout groups"}, {"id": "2ed699f6-cdf5-48c3-b5c6-1a8decf59092", "type": "concept", "title": "Lift studies and randomized controlled tests"}, {"id": "7465bf04-7d01-466c-8352-3dac50fe22ef", "type": "concept", "title": "Power, sample size, and test duration basics"}], "description": "This subtopic introduces the gold standard for learning whether marketing caused an outcome."}, {"id": "9ca2fffb-c573-48f2-a4e1-95929eee1ef6", "type": "subtopic", "title": "Growth optimization", "children": [{"id": "03b68c7d-f62a-4637-8e1f-a66b901ee902", "type": "concept", "title": "Growth loops and funnel diagnostics"}, {"id": "34be9745-0720-4dda-a6b6-ab190c6be4ea", "type": "concept", "title": "ICE, RICE, and prioritization frameworks"}, {"id": "1a52fff9-4ee6-4a61-8806-15e06b32bc61", "type": "concept", "title": "Conversion optimization and landing page testing"}, {"id": "13ba979b-1bd6-40e6-b160-a264a2780806", "type": "concept", "title": "Learning agendas and post-test reviews"}], "description": "Students learn how high-performing teams build repeatable learning systems."}]}, {"id": "8c066692-e108-4376-9820-4a07cb092230", "type": "topic", "title": "Privacy, Ethics, Accessibility, Inclusion, and Responsible Personalization", "description": "Apply consent, privacy, accessibility, fairness, and brand-safety principles to digital marketing decisions.", "children": [{"id": "fcd082cc-c1b0-4b5c-a6c5-c5854b4bbe96", "type": "subtopic", "title": "Privacy and consent", "children": [{"id": "f0d0d1af-41da-4bef-8ad4-8f31382be9d3", "type": "concept", "title": "GDPR, CCPA/CPRA, CAN-SPAM, CASL, and FTC guidance"}, {"id": "8e3f6043-9484-42d8-879a-f42846dc45cd", "type": "concept", "title": "Cookie-less future and first-party data"}, {"id": "d66dc6dd-3a91-45e8-a81f-fa630f72833c", "type": "concept", "title": "Consent management platforms"}, {"id": "f1f1d96a-f4b6-485b-9af4-5de9442229ee", "type": "concept", "title": "Data retention and vendor risk"}], "description": "Privacy is now central to digital strategy. Students learn to design campaigns around consent, transparency, and data minimization."}, {"id": "024a5bff-43f8-4d2b-9634-81139a8a47ac", "type": "subtopic", "title": "Ethical targeting and personalization", "children": [{"id": "7418403b-67b6-4805-a1e3-aafd6bbd3d52", "type": "concept", "title": "Sensitive categories and exclusion risks"}, {"id": "e5bf860e-a7e8-4bd9-a0bb-21573f786e76", "type": "concept", "title": "Dark patterns and deceptive design"}, {"id": "3b1c248f-2cd1-43b6-9c29-049a1ebed40e", "type": "concept", "title": "Algorithmic bias and fairness"}, {"id": "a693ec10-0a06-44e4-b736-6033f8ab5c9a", "type": "concept", "title": "Brand trust and long-term customer relationships"}], "description": "This subtopic helps students evaluate when personalization becomes intrusive, unfair, or manipulative."}, {"id": "a29b9270-696d-4e08-a661-82df9fa56817", "type": "subtopic", "title": "Accessibility and inclusive digital experiences", "children": [{"id": "ac6b228a-4b9c-4af5-878d-5f1e6884c0bc", "type": "concept", "title": "Accessible web content and email"}, {"id": "bf4551fb-ad37-4891-b96c-f06efe9c6b0d", "type": "concept", "title": "Alt text, captions, contrast, and readable design"}, {"id": "767a3b7d-a41a-4cac-942d-18cd99df2a01", "type": "concept", "title": "Inclusive language and representation"}, {"id": "4f601bbf-05ea-40d3-9fbc-4796e9402944", "type": "concept", "title": "Cultural context and localization"}], "description": "Students learn that effective digital marketing should be usable and respectful for diverse audiences."}]}, {"id": "2ee07506-54fd-4c38-ae67-6c56712c7c0f", "type": "topic", "title": "Integrated Digital Campaign Capstone", "description": "Build a complete campaign plan with objectives, creative strategy, channel mix, measurement design, and optimization roadmap.", "children": [{"id": "e724c2df-ed98-487a-a87b-af374c15624c", "type": "subtopic", "title": "Campaign brief and strategic rationale", "children": [{"id": "9decf77c-333d-490d-9e30-7a8495d5a0b3", "type": "concept", "title": "Situation analysis and objectives"}, {"id": "42624736-408e-4103-8c99-86378c07e634", "type": "concept", "title": "Audience, insight, and value proposition"}, {"id": "e1abf4b5-789f-4ba6-8f89-7b2b42cd4d1b", "type": "concept", "title": "Positioning and message strategy"}, {"id": "67ae2f10-b94b-4af8-b28b-d8932e152e7e", "type": "concept", "title": "Channel roles and budget logic"}], "description": "The capstone gives students practice turning analysis into a coherent plan. Students must justify goals, audiences, channels, and creative choices."}, {"id": "5736c4d1-aa20-41a3-ab90-18147b318073", "type": "subtopic", "title": "Execution plan and creative system", "children": [{"id": "875aaf69-2e05-4bcf-ae9a-6970a85ee43e", "type": "concept", "title": "Landing page or website plan"}, {"id": "6fbc1c62-9f87-46a8-93fc-825551f6f57b", "type": "concept", "title": "Search, social, email, content, and paid media assets"}, {"id": "440e7487-6fb5-46a6-bca2-ae17530dd1bc", "type": "concept", "title": "Creative testing matrix"}, {"id": "607f7ddd-4a98-4595-8f7f-e1acd394bb77", "type": "concept", "title": "Timeline, owners, and approvals"}], "description": "Students design the actual campaign assets and workflows needed to launch."}, {"id": "2e3abda1-780f-4c52-80a6-70f966393dbd", "type": "subtopic", "title": "Measurement and optimization plan", "children": [{"id": "1392dece-0042-41cc-9920-91a1da68a18f", "type": "concept", "title": "KPI tree and dashboard mockup"}, {"id": "f7d8a563-4e02-4e74-8230-7067feee09eb", "type": "concept", "title": "Tagging, UTM, and reporting plan"}, {"id": "5a28075c-e9f2-4081-b441-a8e00bbcbb8c", "type": "concept", "title": "Experimentation and attribution plan"}, {"id": "9fb37f2b-4e9a-4515-9294-e4cc72d7731e", "type": "concept", "title": "Risks, ethics, privacy, and accessibility review"}], "description": "The final section requires students to show how they will learn from the campaign after launch."}]}], "dbBacked": true}$digmjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'digital-marketing'
);

update public.learning_paths
set
  title = 'Digital Marketing',
  goal = 'Digital Marketing',
  summary = 'Set goals, audiences, value propositions, funnels, and channel roles for integrated digital campaigns, then cover owned media, search, content, lifecycle, social, partnerships, paid media, omnichannel, martech, analytics, attribution, privacy, and a campaign capstone.',
